// Dartflow leagues and tournament hall. All records are local demo data.
const SETUPS={remote:'Ieder vanuit huis',localone:'Samen aan één bord',localtwo:'Twee borden op locatie',hybrid:'Club & thuis'};
const C=id=>Number(id);
const NOW='2026-11-04';
function schedule(players,leagueId,startDate='2026-11-06'){
  const list=[...players];if(list.length%2)list.push(null);
  const fixtures=[];let n=1;const addDays=(d,num)=>{const x=new Date(d+'T12:00:00');x.setDate(x.getDate()+num);return x.toISOString().slice(0,10);};
  for(let round=0;round<list.length-1;round++){
    for(let j=0;j<list.length/2;j++){
      const pair=[list[j],list[list.length-1-j]];
      if(pair.every(Boolean))fixtures.push({id:`${leagueId}-${n++}`,round:round+1,players:pair,status:'scheduled',time:`${addDays(startDate,round*7)}T20:00`,proposedTime:null,score:null,matchId:null});
    }
    list.splice(1,0,list.pop());
  }
  return fixtures;
}
function seededLeague({id,name,division,players,setup,legLimit,bestOf,startDate,joined=true}){
  const fixtures=schedule(players,id,startDate);
  fixtures.slice(0,4).forEach((f,i)=>{f.status='finished';f.score=legLimit?(i===1?[4,4]:i%2?[3,5]:[5,3]):i%2?[1,3]:[3,2];f.mockResult=true;});
  return {id,name,division,season:'Winter 2026',players:[...players],capacity:16,setup,legLimit,bestOf,cameraRequired:setup!=='localone',startDate,joined,fixtures,teamName:'Puinruimers Gold',teams:[{id:1,name:'Puinruimers Gold',players:[1,3,5,7]},{id:2,name:'Dartflow Royals',players:[2,4,6,8]}],lineup:{singles:[1,3,5,7],doubles:[[1,3],[5,7]]}};
}
export function createCompetitions(ctx){
  const {esc,icon,button,header,badge,avatar,P,short,showModal,closeModal,toast,save,render,go}=ctx;
  const adm=()=>ctx.db.role==='admin';
  const state=()=>ctx.db.play;
  const scope=()=>ctx.scopeId?.()??null;
  const scopeLabel=()=>ctx.scopeName?.()||'Dartflow Wereldwijd';
  const inScope=record=>!ctx.scopeId||(record.clubId==null?null:C(record.clubId))===(scope()==null?null:C(scope()));
  const scopedLeagues=()=>state().leagues.filter(inScope);
  const scopedTournaments=()=>ctx.db.tournaments.filter(inScope);
  const selected=()=>scopedLeagues().find(x=>x.id===state().selectedLeague)||scopedLeagues()[0];
  const tournament=()=>scopedTournaments().find(t=>t.id===state().selectedHall)||scopedTournaments()[0];
  function participantPool(){const approved=ctx.db.players.filter(p=>p.status==='approved');if(scope()==null||!ctx.scopeId)return approved.map(p=>p.id);const club=state().clubs?.items?.find(c=>c.id===C(scope()));const ids=(club?.members||[]).map(m=>typeof m==='number'?m:m.id);return approved.filter(p=>ids.includes(p.id)).map(p=>p.id);}
  function setTeamParticipants(l){const split=Math.min(4,Math.ceil(l.players.length/2)),first=l.players.slice(0,split),second=l.players.slice(split,split+4);l.teams=[{id:1,name:l.clubId?'Clubteam Gold':'Dartflow Gold',players:first},{id:2,name:'Dartflow Royals',players:second}];l.lineup={singles:[...first],doubles:Array.from({length:Math.floor(first.length/2)},(_,i)=>first.slice(i*2,i*2+2))};}

  function init(){
    ctx.db.play??={};
    state().leagues??=[seededLeague({id:501,name:'Dartflow Thuiscompetitie',division:'Gold Division',players:[1,2,3,4,5,6,7,8],setup:'remote',legLimit:8,bestOf:5,startDate:'2026-10-30'}),seededLeague({id:502,name:'Puinruimers Club League',division:'Open Division',players:[9,10,11,12,13,14,15,16],setup:'hybrid',legLimit:null,bestOf:5,startDate:'2026-11-06',joined:false})];
    state().selectedLeague??=501;state().leagueTab??='standings';state().fixtureFilter??='mine';state().selectedHall??=1;
    state().tournamentBrackets??={};state().tournamentCheckins??={};
    const clubId=state().clubs?.items?.find(club=>club.name==='De Puinruimers')?.id||701;
    for(const l of state().leagues){
      if(!Object.hasOwn(l,'clubId'))l.clubId=l.id===501?clubId:null;
      if(l.id===501&&l.name==='DartRush Thuiscompetitie')l.name='Dartflow Thuiscompetitie';
      if(l.id===502&&['Puinruimers Club League','DartRush Global League'].includes(l.name))l.name='Dartflow Global League';
      for(const team of l.teams||[]){
        if(team.name==='DartRush Royals')team.name='Dartflow Royals';
        if(team.name==='DartRush Gold')team.name='Dartflow Gold';
      }
      if(l.teams?.some(team=>team.players.some(id=>!l.players.includes(id))))setTeamParticipants(l);
    }
    for(const t of ctx.db.tournaments){
      if(!Object.hasOwn(t,'clubId'))t.clubId=clubId;
      if(t.id===200&&t.name==='DartRush World Series')t.name='Dartflow World Series';
    }
    if(!ctx.db.tournaments.some(t=>t.id===200))ctx.db.tournaments.push({id:200,name:'Dartflow World Series',format:'Knock-out',status:'active',date:'2026-11-08',capacity:64,players:32,progress:25,location:'Wereldwijd · thuisborden',score:501,bestOf:5,clubId:null});
    const leagues=scopedLeagues(),tournaments=scopedTournaments();
    if(!leagues.some(l=>l.id===state().selectedLeague))state().selectedLeague=leagues[0]?.id??null;
    if(!tournaments.some(t=>t.id===state().selectedHall))state().selectedHall=tournaments[0]?.id??null;
  }
  function standings(l){
    const rows=l.players.map(id=>({id,played:0,win:0,draw:0,loss:0,for:0,against:0,points:0}));
    for(const f of l.fixtures){if(!f.score||f.status!=='finished')continue;f.players.forEach((id,i)=>{const p=rows.find(x=>x.id===id);if(!p)return;p.played++;p.for+=f.score[i];p.against+=f.score[1-i];if(f.score[i]>f.score[1-i]){p.win++;p.points+=2;}else if(f.score[i]===f.score[1-i]){p.draw++;p.points++;}else p.loss++;});}
    return rows.sort((a,b)=>b.points-a.points||(b.for-b.against)-(a.for-a.against)||b.for-a.for||a.id-b.id);
  }
  const fmt=val=>{if(!val)return 'Nog afspreken';const d=new Date(val);return Number.isNaN(d.getTime())?'Nog afspreken':new Intl.DateTimeFormat('nl-NL',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(d);};
  const profile=(id,small=false)=>`<span class="dr-inline">${avatar(id,small?'sm':'')}<span>${esc(P(id).name)}</span></span>`;
  const leagueRules=l=>`${l.legLimit?`${l.legLimit} vaste legs · gelijkspel mogelijk`:`Best of ${l.bestOf}`} · 501 dubbel uit`;
  function standingsTable(l){const rows=standings(l);return `<div class="panel full-table dr-standing"><table class="table"><thead><tr><th>#</th><th>Speler</th><th>G</th><th>W</th><th>GL</th><th>V</th><th>Legs</th><th>Saldo</th><th>Punten</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.id===1?'qualification':''}"><td>${i+1}</td><td>${profile(r.id,true)}${r.id===1?' <small class="subtle-label">Jij</small>':''}</td><td>${r.played}</td><td>${r.win}</td><td>${r.draw}</td><td>${r.loss}</td><td>${r.for}–${r.against}</td><td>${r.for-r.against>0?'+':''}${r.for-r.against}</td><td class="stat-gold"><b>${r.points}</b></td></tr>`).join('')}</tbody></table></div><p class="subtle-label">Winst 2 punten · gelijkspel 1 · verlies 0. Bij gelijk aantal punten: legsaldo, daarna gewonnen legs. Bestaande uitslagen zijn voorbeelddata; bevestigde demowedstrijden tellen direct mee.</p>`;}
  function fixtureCard(l,f){const mine=f.players.includes(1),m=f.matchId&&ctx.db.matches.find(x=>x.id===f.matchId);return `<article class="panel dr-fixture"><div class="dr-inline" style="justify-content:space-between"><span class="eyebrow">Speelweek ${f.round}</span>${badge(f.status==='finished'?'Afgerond':f.status==='proposed'?'Tijdvoorstel':m?.status==='live'?'In wedstrijd':'Gepland',f.status==='finished'?'approved':f.status==='proposed'?'pending':m?.status==='live'?'live':'blue')}</div><div class="dr-fixture-players" style="margin:15px 0">${profile(f.players[0],true)}<b class="stat-gold">${f.score?f.score.join(' – '):'vs'}</b>${profile(f.players[1],true)}</div><div class="dr-meta">${icon('calendar')} ${fmt(f.status==='proposed'?f.proposedTime:f.time)} &nbsp; ${icon(l.setup==='remote'?'wifi':'pin')} ${esc(SETUPS[l.setup])}</div>${f.status==='proposed'?`<p class="subtle-label">Tijdvoorstel wacht op akkoord van de tegenstander.${f.message?`<br>Bericht: ${esc(f.message)}`:''}</p>`:''}<div class="dr-inline" style="justify-content:space-between;margin-top:15px;flex-wrap:wrap">${f.status==='finished'?(f.matchId?button('Bekijk uitslag','comp-open-match','small ghost',`data-id="${f.matchId}"`):'<span class="subtle-label">Voorbeelduitslag</span>'):mine?`${button(icon('calendar')+' Tijd afspreken','comp-plan','small ghost',`data-id="${esc(f.id)}"`)}${f.status==='proposed'?button('Simuleer akkoord','comp-accept-time','small',`data-id="${esc(f.id)}"`):button(m?'Hervat wedstrijd':'Naar wedstrijdkamer','comp-start','gold small',`data-id="${esc(f.id)}"`)}`:adm()?button('Simuleer uitslag','comp-simulate-fixture','small ghost',`data-id="${esc(f.id)}"`):'<span class="subtle-label">Partij van clubgenoten</span>'}${m?button(icon('eye')+' Kijken','comp-watch','small ghost',`data-id="${m.id}"`):''}</div></article>`;}
  function teamView(l){return `<div class="notice">${icon('info')}Teamopstelling als werkend voorbeeld. Je kunt de singles en koppels wijzigen; het spelen van dubbels volgt in een latere bouwfase.</div><div class="dr-grid dr-grid-2 dr-team-grid">${l.teams.map(t=>`<section class="panel dr-card"><div class="dr-inline" style="justify-content:space-between"><h2>${esc(t.name)}</h2>${badge(t.id===1?'Jouw team':'Tegenstander',t.id===1?'pending':'blue')}</div>${t.players.map(id=>`<div class="dr-team-player" style="padding:11px 0;border-bottom:1px solid var(--line)">${profile(id,true)}</div>`).join('')}</section>`).join('')}</div><section class="panel" style="margin-top:18px"><div class="dr-inline" style="justify-content:space-between"><h2>De opstelling</h2>${button(icon('edit')+' Opstelling wijzigen','comp-lineup','ghost small')}</div><div class="dr-grid dr-grid-2"><div><h3>Singles</h3>${l.lineup.singles.map((id,i)=>`<p class="subtle-label">Partij ${i+1} · ${esc(P(id).name)}</p>`).join('')}</div><div><h3>Dubbels</h3>${l.lineup.doubles.map((ids,i)=>`<p class="subtle-label">Koppel ${i+1} · ${ids.map(id=>esc(short(id))).join(' & ')}</p>`).join('')}</div></div></section>`;}
  function leagues(){init();const l=selected();if(!l)return header('Jouw competitie. <em>Jouw speelveld.</em>',`Er is nog geen competitie binnen ${esc(scopeLabel())}.`,adm()?button(icon('plus')+' Competitie maken','comp-new','gold'):'')+ctx.empty('Nog geen competitie',adm()?'Maak een competitie voor deze omgeving en kies de spelregels.':'De organisator kan een competitie voor deze omgeving klaarzetten.','trophy');const rows=standings(l),tab=state().leagueTab,mine=rows.find(r=>r.id===1);const filtered=l.fixtures.filter(f=>state().fixtureFilter==='all'||state().fixtureFilter==='mine'&&f.players.includes(1)||state().fixtureFilter==='upcoming'&&f.status!=='finished'||state().fixtureFilter==='finished'&&f.status==='finished');return header('Jouw seizoen. <em>Elke leg telt.</em>',`Competities binnen ${esc(scopeLabel())}. Speel vanuit huis, in de club of gecombineerd.`,adm()?button(icon('plus')+' Competitie maken','comp-new','gold'):button(icon('users')+' Club uitnodigen','comp-invite','gold'))+`<div class="notice">${icon('info')}Werkende competitiedemo op dit apparaat. Tijdvoorstellen en tegenstanders kun je expliciet simuleren; er worden geen uitnodigingen verstuurd.</div><div class="dr-grid dr-grid-2" style="margin-bottom:22px">${scopedLeagues().map(item=>`<article class="panel dr-league-card"><div class="dr-inline" style="justify-content:space-between">${badge(item.division,item.id===l.id?'pending':'blue')}${badge(item.players.includes(1)?'Lid':'Open voor inschrijving',item.players.includes(1)?'approved':'')}</div><h2 style="margin:13px 0 5px">${esc(item.name)}</h2><p class="subtle-label">${esc(item.clubId?scopeLabel():'Dartflow Wereldwijd')} · ${esc(item.season)} · ${item.players.length}/${item.capacity} spelers · ${esc(SETUPS[item.setup])}</p><p class="dr-meta">${esc(leagueRules(item))}</p><div class="dr-inline" style="margin-top:17px">${button(item.id===l.id?'Geselecteerd':'Bekijk competitie','comp-select',item.id===l.id?'gold small':'ghost small',`data-id="${item.id}"`)}${!item.players.includes(1)?button('Deelnemen','comp-join','small',`data-id="${item.id}"`):''}</div></article>`).join('')}</div><div class="dr-inline dr-league-toolbar" style="justify-content:space-between;margin:20px 0"><div><div class="eyebrow">${esc(l.season)} · ${esc(l.division)}</div><h2 style="margin:5px 0">${esc(l.name)}</h2></div>${button(icon('download')+' Deel competitie','comp-invite','ghost small')}</div><div class="metrics">${ctx.metric('Spelers in de divisie',l.players.length,'users','<b>WINTER</b> 2026')}${ctx.metric('Afgeronde partijen',l.fixtures.filter(f=>f.status==='finished').length,'target','<b>GEDEELDE</b> stand')}${ctx.metric('Jouw punten',mine?.points??'–','trophy',mine?`<b>${mine.played}</b> wedstrijden`:'<b>SCHRIJF</b> je in')}${ctx.metric('Jouw legsaldo',mine?`${mine.for-mine.against>0?'+':''}${mine.for-mine.against}`:'–','chart','<b>ELKE</b> leg telt')}</div><div class="tabs">${[['standings','Stand & divisie'],['fixtures','Wedstrijdprogramma'],['teams','Teams & opstelling']].map(([v,label])=>`<button type="button" class="tab ${tab===v?'active':''}" data-action="comp-tab" data-value="${v}">${label}</button>`).join('')}</div>${tab==='standings'?standingsTable(l):tab==='teams'?teamView(l):`<div class="toolbar"><div class="tabs">${[['mine','Mijn partijen'],['upcoming','Komende'],['finished','Afgerond'],['all','Alle partijen']].map(([v,label])=>`<button type="button" class="tab ${state().fixtureFilter===v?'active':''}" data-action="comp-filter" data-value="${v}">${label}</button>`).join('')}</div><span class="subtle-label">${filtered.length} partijen · ${esc(leagueRules(l))}</span></div><div class="dr-grid dr-grid-2">${filtered.map(f=>fixtureCard(l,f)).join('')}</div>${!filtered.length?ctx.empty('Je bent nog niet ingedeeld','Schrijf je in voor deze competitie of bekijk alle partijen.','calendar'):''}`}`;}
  function makeBracket(t){if(state().tournamentBrackets[t.id])return state().tournamentBrackets[t.id];const available=ctx.db.players.filter(p=>p.status==='approved').slice(0,8).map(p=>p.id);while(available.length<8)available.push(null);const pairs=[[available[0],available[4]],[available[1],available[5]],[available[2],available[6]],[available[3],available[7]]];const rounds=[pairs.map(players=>({players,score:null,winner:null,matchId:null})),Array.from({length:2},()=>({players:[null,null],score:null,winner:null,matchId:null})),[{players:[null,null],score:null,winner:null,matchId:null}]];state().tournamentBrackets[t.id]={rounds,champion:null,cameraRequired:true,created:true};if(t.status==='finished'){const b=state().tournamentBrackets[t.id];b.rounds.forEach((rr,ri)=>rr.forEach((node,ni)=>fillWinner(b,ri,ni,ri===2?[4,2]:[3,1])));}return state().tournamentBrackets[t.id];}
  function checkins(t){if(!state().tournamentCheckins[t.id]){state().tournamentCheckins[t.id]=Object.fromEntries(ctx.db.players.filter(p=>p.status==='approved').slice(0,8).map((p,i)=>[p.id,{checked:p.id!==1&&i!==1,location:i%3===0?'club':'home',state:p.id!==1&&i!==1?'ready':'waiting'}]));}return state().tournamentCheckins[t.id];}
  function fillWinner(b,round,index,score){const node=b.rounds[round][index];node.score=[...score];node.winner=node.players[score[0]>score[1]?0:1];if(round<2){const next=b.rounds[round+1][Math.floor(index/2)];next.players[index%2]=node.winner;}else b.champion=node.winner;}
  function bracketHtml(b){return `<div class="dr-bracket">${b.rounds.map((round,ri)=>`<section class="dr-bracket-round"><h3 class="eyebrow">${['Kwartfinales','Halve finales','Finale'][ri]}</h3>${round.map((node,ni)=>`<article class="panel dr-bracket-game" style="padding:0;overflow:hidden">${node.players.map((id,j)=>`<div class="dr-bracket-player ${node.winner===id&&id?'qualification':''}" style="padding:11px 12px;display:flex;justify-content:space-between;gap:8px;border-bottom:1px solid var(--line)"><span class="dr-inline">${id?avatar(id,'sm'):icon('user')}<span>${id?esc(short(id)):'Winnaar vorige ronde'}</span></span><b class="stat-gold">${node.score?node.score[j]:'–'}</b></div>`).join('')}<div class="dr-inline" style="padding:8px 12px;justify-content:space-between"><small class="subtle-label">${node.winner?'Bevestigde uitslag':node.matchId?'In wedstrijdkamer':node.players.every(Boolean)?'Klaar om te spelen':'Wacht op uitslag'}</small>${node.matchId?button(icon('eye'),'comp-watch','small ghost',`data-id="${node.matchId}" aria-label="Wedstrijd bekijken"`):''}</div></article>`).join('')}</section>`).join('')}</div>`;}
  function nodeForRick(b){for(let r=0;r<b.rounds.length;r++)for(let i=0;i<b.rounds[r].length;i++){const n=b.rounds[r][i];if(!n.winner&&n.players.includes(1)&&n.players.every(Boolean))return{node:n,round:r,index:i};}return null;}
  function hallRoster(t,b){const roster=checkins(t),nodes=b.rounds.flat(),canCheck=['active','open'].includes(t.status);return `<section class="panel"><div class="dr-inline" style="justify-content:space-between;flex-wrap:wrap"><h2>Deelnemers · ${esc(t.name)}</h2>${adm()?button('Simuleer overige check-ins','hall-checkin-others','ghost small',canCheck?'':'disabled'):''}</div>${Object.entries(roster).map(([id,p])=>{const inGame=nodes.some(n=>n.matchId&&!n.winner&&n.players.includes(C(id)));return `<div class="dr-roster-row" style="padding:12px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:8px"><div class="dr-inline">${avatar(C(id),'sm')}<div><strong style="font-size:11px">${esc(P(C(id)).name)}${C(id)===1?' · Jij':''}</strong><div class="dr-roster-loc subtle-label">${adm()?`<select class="input" data-hall-location="${id}" aria-label="Speellocatie ${esc(P(C(id)).name)}" style="font-size:9px;padding:4px 6px;margin-top:5px" ${inGame?'disabled':''}><option value="home" ${p.location==='home'?'selected':''}>Thuisbord</option><option value="club" ${p.location==='club'?'selected':''}>Clubhuis</option></select>`:p.location==='home'?'Thuisbord':'Clubhuis'}</div></div></div>${badge(inGame?'Speelt':p.checked?'Klaar':'Wacht',inGame?'live':p.checked?'approved':'pending')}</div>`;}).join('')}<p class="subtle-label">De organisator kan de speellocatie wijzigen voordat de wedstrijdkamer is gestart. Alleen clubpartijen krijgen een fysiek bord.</p></section>`;}
  function hallNext(t,b){const roster=checkins(t),rick=roster[1],next=nodeForRick(b),canCheck=['active','open'].includes(t.status),m=next?.node.matchId&&ctx.db.matches.find(m=>m.id===next.node.matchId);if(b.champion)return `<section class="panel" style="text-align:center;margin-bottom:20px"><div class="dr-inline" style="justify-content:center">${icon('crown')}${badge('TOERNOOIWINNAAR','approved')}</div><h2 style="font-family:var(--display);font-size:34px;margin:13px 0">${esc(P(b.champion).name)}</h2><p class="subtle-label">De finale is bevestigd. Alle uitslagen staan bij de knock-out en wedstrijden.</p>${button('Bekijk de finale','hall-tab','gold small','data-value="knockout"')}</section>`;return `<section class="panel dr-league-summary" style="margin-bottom:20px"><div class="dr-inline" style="justify-content:space-between;flex-wrap:wrap"><div><div class="eyebrow">Jouw volgende stap</div><h2 style="margin:7px 0">${!rick?.checked?'Meld je aan bij de oche.':next?`${esc(short(1))} tegen ${esc(short(next.node.players.find(id=>id!==1)))}`:'Wacht op de volgende uitslag.'}</h2><p class="subtle-label">${!canCheck?'Dit toernooi is nog niet speelbaar.':!rick?.checked?'Check in en kies of je thuis of in het clubhuis speelt.':next?'Je wedstrijdkamer bevat beeldcontrole, score-invoer en uitslagbevestiging.':'Je bent uitgeschakeld of je volgende tegenstander is nog niet bekend.'}</p></div><div class="dr-inline">${!rick?.checked?button(icon('check')+' Ik ben aanwezig','hall-checkin','gold',canCheck?'':'disabled'):next?button(m?'Hervat wedstrijdkamer':'Open mijn wedstrijd','hall-start','gold',t.status==='active'?'':'disabled'):badge('Je bent ingecheckt','approved')}</div></div>${rick?.checked?`<div class="dr-inline"><span class="subtle-label">Jouw opstelling:</span><select class="input" id="comp-hall-location" aria-label="Jouw speellocatie"><option value="home" ${rick.location==='home'?'selected':''}>Ik speel thuis</option><option value="club" ${rick.location==='club'?'selected':''}>Ik speel in de club</option></select></div>`:''}</section>`;}
  function hallKnockout(t,b){return `<section class="panel"><div class="dr-inline" style="justify-content:space-between;flex-wrap:wrap;margin-bottom:18px"><div><div class="eyebrow">${esc(t.name)}</div><h2>Het knock-outschema</h2></div>${adm()?button(icon('bolt')+' Simuleer volgende ronde','hall-simulate','ghost small',t.status==='active'&&!b.champion?'':'disabled'):''}</div>${bracketHtml(b)}<p class="subtle-label">Winnaars uit bevestigde wedstrijdkamers schuiven automatisch door. De simulatieknop vult alleen partijen zonder een lopende kamer in.</p></section>`;}
  function hallMatches(t,b){const rows=b.rounds.flatMap((round,ri)=>round.map((node,ni)=>({node,round:ri,index:ni})));const next=nodeForRick(b);return `<section class="panel full-table"><div style="padding:12px"><div class="eyebrow">${esc(t.name)}</div><h2>Alle toernooipartijen</h2></div><table class="table"><thead><tr><th>Ronde</th><th>Wedstrijd</th><th>Uitslag</th><th>Status</th><th>Actie</th></tr></thead><tbody>${rows.map(({node:n,round:r,index:i})=>{const m=n.matchId&&ctx.db.matches.find(m=>m.id===n.matchId),myNext=next?.round===r&&next?.index===i;return `<tr><td>${['Kwartfinale','Halve finale','Finale'][r]}</td><td>${n.players.map(id=>id?esc(P(id).name):'Winnaar vorige ronde').join(' vs ')}</td><td class="score">${n.score?n.score.join(' – '):'–'}</td><td>${badge(n.winner?'Bevestigd':m?.status==='finished'?'Uitslag controleren':m?'In wedstrijdkamer':n.players.every(Boolean)?'Ingepland':'Wacht op uitslag',n.winner?'approved':m?'live':'pending')}</td><td>${n.matchId?button(n.winner?'Bekijk uitslag':'Open kamer','comp-open-match','small ghost',`data-id="${n.matchId}"`):myNext?button('Klaarzetten','hall-start','small gold',t.status==='active'?'':'disabled'):'<span class="subtle-label">Nog niet gestart</span>'}</td></tr>`;}).join('')}</tbody></table></section>`;}
  function communityRoomFor(t){const rooms=state().community?.rooms||[];return rooms.find(r=>r.type==='tournament'&&C(r.tournamentId)===t.id)||(t.id===1?rooms.find(r=>r.type==='tournament'&&!r.tournamentId):null);}
  function hallCommunity(t){const room=communityRoomFor(t),members=room?.members||[];return `<div class="dr-grid dr-grid-2"><section class="panel dr-card"><div class="dr-inline">${icon('users')}${badge('TOERNOOIKAMER','pending')}</div><h2 style="margin:16px 0 8px">${esc(room?.name||`${t.name} · Spelerslounge`)}</h2><p class="subtle-label">${esc(room?.description||`De ontmoetingsplek voor spelers van ${t.name}. Bespreek de planning, zoek je tegenstander en volg het toernooi samen.`)}</p><div class="dr-inline" style="margin:19px 0;flex-wrap:wrap">${badge(`${members.length||0} leden`,'blue')}${badge(`Maximaal ${room?.maxMembers||32} leden`)}${badge('Gesprekken in deze demo blijven lokaal')}</div>${button(icon('arrow')+' Open toernooikamer','hall-community','gold')}<p class="subtle-label" style="margin-bottom:0">De kamer hoort uitsluitend bij dit toernooi en opent in Chatkamers.</p></section><section class="panel dr-card"><h2>Van lobby naar partij</h2><p class="subtle-label">Gebruik de toernooikamer voor contact met deelnemers. De aparte wedstrijdkamer bevat het bordbeeld, de scores en de beurtvolgorde.</p><div class="dr-inline" style="flex-wrap:wrap;margin-top:18px">${button('Bekijk deelnemers','hall-tab','ghost small','data-value="participants"')}${button('Bekijk wedstrijden','hall-tab','ghost small','data-value="matches"')}</div></section></div>`;}
  function venueList() {
    const events = ctx.scopedVenueEvents?.() || [];
    if (!events.length) return '';
    return `<section class="panel" style="margin-bottom:20px"><div class="eyebrow">Fysieke speelzaal</div><h2>Toernooien op locatie</h2>${events.map(event => `<div class="dr-inline" style="justify-content:space-between;gap:12px;padding:10px 0"><strong>${esc(event.name)}</strong>${button('Open speeldag', 'venue-open-event', 'small ghost', `data-event-id="${esc(event.id)}"`)}</div>`).join('')}</section>`;
  }
  function hall(){
    init();const t=tournament();if(!t)return header('Jouw toernooi. <em>Jouw speelzaal.</em>',`Er is nog geen toernooi binnen ${esc(scopeLabel())}.`,adm()?button(icon('plus')+' Toernooi maken','new-tour','gold'):'')+venueList()+ctx.empty('Nog geen toernooi voor online of hybride spel',adm()?'Maak een clubtoernooi in deze omgeving.':'De organisator kan hier een clubtoernooi toevoegen.','trophy');const b=makeBracket(t),roster=checkins(t),nodes=b.rounds.flat(),ready=Object.values(roster).filter(p=>p.checked).length;
    state().hallTabs??={};const tab=state().hallTabs[t.id]||'overview';
    const metrics=`<div class="metrics">${ctx.metric('Ingecheckte spelers',`${ready} / ${Object.keys(roster).length}`,'users','<b>LOKALE</b> demo')}${ctx.metric('Thuisborden',Object.values(roster).filter(p=>p.location==='home').length,'wifi','<b>ONLINE</b> opstelling')}${ctx.metric('Clubspelers',Object.values(roster).filter(p=>p.location==='club').length,'pin','<b>OP</b> locatie')}${ctx.metric('Afgeronde partijen',nodes.filter(n=>n.winner).length,'trophy','<b>7</b> tot de titel')}</div>`;
    let content='';
    if(tab==='participants')content=hallRoster(t,b);
    else if(tab==='pools')content=t.format?.includes('Poules')?(ctx.renderPools?ctx.renderPools(t.id):`<section class="panel"><h2>Poules van ${esc(t.name)}</h2><p class="subtle-label">De onderstaande ingedeelde spelers vormen het poulevoorbeeld van dit toernooi.</p>${hallRoster(t,b)}</section>`):`<section class="panel dr-card"><h2>Rechtstreeks naar de knock-out.</h2><p class="subtle-label">${esc(t.name)} gebruikt het format ${esc(t.format||'Knock-out')}. Er is voor dit toernooi geen poulefase.</p>${button('Bekijk knock-out','hall-tab','gold small','data-value="knockout"')}</section>`;
    else if(tab==='knockout')content=hallKnockout(t,b);
    else if(tab==='matches')content=hallMatches(t,b);
    else if(tab==='community')content=hallCommunity(t);
    else content=metrics+hallNext(t,b)+`<div class="dr-grid dr-grid-3"><section class="panel dr-card">${icon('users')}<h2>Deelnemers</h2><p class="subtle-label">${ready} van de ${Object.keys(roster).length} voorbeeldspelers zijn ingecheckt. Bekijk hun speellocatie en beschikbaarheid.</p>${button('Bekijk deelnemers','hall-tab','ghost small','data-value="participants"')}</section><section class="panel dr-card">${icon('bracket')}<h2>De route naar de titel</h2><p class="subtle-label">${esc(t.format||'Knock-out')} · ${t.score||501} dubbel uit. Poules en knock-out staan binnen dit toernooi bij elkaar.</p>${button('Bekijk knock-out','hall-tab','ghost small','data-value="knockout"')}</section><section class="panel dr-card">${icon('users')}<h2>De toernooikamer</h2><p class="subtle-label">Praat met deelnemers, spreek af met je tegenstander en blijf samen bij de actie.</p>${button('Naar de spelerslounge','hall-tab','ghost small','data-value="community"')}</section></div>`;
    return header('Jouw toernooi. <em>Jouw speelzaal.</em>',`Toernooien binnen ${esc(scopeLabel())}. Deelnemers, poules, partijen en gesprekken blijven bij elkaar.`,adm()?button(icon('settings')+' Toernooien beheren','nav-tournaments','ghost'):'')+venueList()+`<div class="toolbar"><select class="input" name="tournament" id="comp-hall-select" aria-label="Kies een toernooi">${scopedTournaments().map(item=>`<option value="${item.id}" ${item.id===t.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select><div class="dr-inline">${badge(t.status==='active'?'Toernooi actief':t.status==='open'?'Inschrijving open':t.status==='finished'?'Afgerond':'Nog in planning',t.status==='active'?'live':t.status==='open'?'pending':'blue')}${badge('Camera verplicht','pending')}</div></div><section class="panel" style="margin-bottom:20px"><div class="eyebrow">${esc(t.location||'Online & op locatie')}</div><h2 style="font-family:var(--display);font-size:30px;margin:5px 0">${esc(t.name)}</h2><p class="subtle-label" style="margin:0">${esc(t.format||'Knock-out')} · ${t.score||501} dubbel uit · Best of ${t.bestOf||5} · ${new Intl.DateTimeFormat('nl-NL',{day:'numeric',month:'long',year:'numeric'}).format(new Date((t.date||NOW)+'T12:00:00'))}</p>${t.id===1?`<a class="btn gold small dr-section-gap" href="#venue" data-action="venue-open-event" data-event-id="1">${icon('pin')} Toernooiregie op locatie</a>`:''}</section><nav class="tabs" aria-label="Toernooionderdelen">${[['overview','Overzicht'],['participants','Deelnemers'],['pools','Poules'],['knockout','Knock-out'],['matches','Wedstrijden'],['community','Toernooikamer']].map(([key,label])=>`<button type="button" class="tab ${tab===key?'active':''}" data-action="hall-tab" data-value="${key}" ${tab===key?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="notice">${icon('info')}Werkende toernooidemo met acht voorbeeldspelers. Andere spelers en hun uitslagen worden alleen aangepast via expliciete simulatieknoppen.</div>${content}`;
  }
  function newLeague(){if(!adm())return;const pool=participantPool();if(pool.length<2){toast('Er zijn minimaal twee goedgekeurde spelers in deze omgeving nodig.');return;}showModal('Maak jouw competitie.',`Maak een competitie binnen ${esc(scopeLabel())} en genereer direct het speelschema.`,`<form data-form="comp-new"><label class="field">Naam<input class="input" name="name" required maxlength="65" placeholder="Bijv. Dartflow Winter League"></label><div class="field-row"><label class="field">Divisie<input class="input" name="division" value="Open Division" maxlength="50" required></label><label class="field">Aantal spelers<select name="size">${[2,3,4,8,16].filter(n=>n<=pool.length).map(n=>`<option value="${n}" ${n===(pool.length>=8?8:pool.length>=4?4:pool.length)?'selected':''}>${n} spelers</option>`).join('')}</select></label></div><div class="field-row"><label class="field">Startdatum<input class="input" type="date" name="date" value="2026-11-13" required></label><label class="field">Speelopstelling<select name="setup">${Object.entries(SETUPS).map(([v,label])=>`<option value="${v}">${label}</option>`).join('')}</select></label></div><div class="field-row"><label class="field">Format<select name="format"><option value="best5">Best of 5</option><option value="best7">Best of 7</option><option value="fixed8">8 vaste legs · gelijkspel</option><option value="fixed10">10 vaste legs · gelijkspel</option></select></label><label class="field">Bordcamera<select name="camera"><option value="yes">Verplicht</option><option value="no">Optioneel</option></select></label></div><div class="notice">${icon('info')}We vullen de competitie met goedgekeurde voorbeeldspelers uit deze omgeving. Je kunt daarna vanuit het programma een echte demopartij spelen.</div><div class="inline-error" id="comp-form-error"></div><div class="modal-actions">${button('Annuleren','close-modal','ghost')}<button class="btn gold">${icon('check')} Competitie aanmaken</button></div></form>`);}
  function findFixture(id){for(const l of scopedLeagues()){const f=l.fixtures.find(f=>f.id===id);if(f)return{l,f};}return null;}
  function planFixture(id){const found=findFixture(id);if(!found)return;const{f}=found;if(f.status==='finished')return;showModal('Spreek een speeltijd af.','In deze demo kun je het akkoord van je tegenstander daarna zelf simuleren.',`<form data-form="comp-plan"><input type="hidden" name="id" value="${esc(f.id)}"><div class="dr-inline" style="margin-bottom:18px">${profile(f.players[0],true)}<span>vs</span>${profile(f.players[1],true)}</div><label class="field">Voorgestelde datum en tijd<input class="input" type="datetime-local" name="time" value="${esc(f.proposedTime||f.time||'2026-11-06T20:00')}" required></label><label class="field">Bericht aan je tegenstander<input class="input" name="message" maxlength="150" placeholder="Bijv. Past vrijdagavond voor jou?"></label><div class="inline-error" id="comp-form-error"></div><div class="modal-actions">${button('Annuleren','close-modal','ghost')}<button class="btn gold">Tijdvoorstel bewaren</button></div></form>`);}
  function lineupForm(){const l=selected();if(!l)return;const team=l.teams[0];showModal('Zet je team klaar.','Kies de singles en koppels voor deze voorbeeldontmoeting.',`<form data-form="comp-lineup"><label class="field">Teamnaam<input class="input" name="name" value="${esc(team.name)}" required maxlength="50"></label><div class="field-row">${l.lineup.singles.map((id,i)=>`<label class="field">Single ${i+1}<select name="single${i}">${team.players.map(pid=>`<option value="${pid}" ${id===pid?'selected':''}>${esc(P(pid).name)}</option>`).join('')}</select></label>`).join('')}</div>${l.lineup.doubles.map((ids,i)=>`<div class="field-row">${ids.map((id,j)=>`<label class="field">Koppel ${i+1} · speler ${j+1}<select name="double${i}${j}">${team.players.map(pid=>`<option value="${pid}" ${id===pid?'selected':''}>${esc(P(pid).name)}</option>`).join('')}</select></label>`).join('')}</div>`).join('')}<div class="inline-error" id="comp-form-error"></div><div class="modal-actions">${button('Annuleren','close-modal','ghost')}<button class="btn gold">Opstelling opslaan</button></div></form>`);}
  async function copyInvite(){const l=selected();if(!l)return;const url=`${location.origin}${location.pathname}#leagues`;try{await navigator.clipboard.writeText(`${l.name} — ${url}`);toast('Competitielink gekopieerd.');}catch{showModal('Deel je competitie.','Deze link opent de lokale competitiedemo; gegevens worden niet tussen apparaten gesynchroniseerd.',`<label class="field">Uitnodigingslink<input class="input" readonly value="${esc(url)}"></label><div class="modal-actions">${button('Sluiten','close-modal','gold')}</div>`);}}
  function startFixture(id){const found=findFixture(id);if(!found)return;const{l,f}=found;if(!f.players.includes(1)){toast('Open je eigen partij of gebruik een expliciete uitslagsimulatie.');return;}if(f.status==='finished'){if(f.matchId)ctx.openMatch(f.matchId);return;}if(f.status==='proposed'){toast('Laat eerst het tijdvoorstel bevestigen.');return;}if(f.matchId){ctx.openMatch(f.matchId);return;}const matchId=ctx.createGame({opponentId:f.players.find(id=>id!==1),startScore:501,bestOf:l.bestOf||5,legLimit:l.legLimit||null,setup:l.setup,type:'league',cameraRequired:l.cameraRequired,fixtureId:f.id,leagueId:l.id,clubId:l.clubId??null});if(matchId){f.matchId=matchId;save();}}
  function startHall(){const t=tournament();if(!t)return;const b=makeBracket(t),roster=checkins(t);if(t.status!=='active')return toast('Dit toernooi is nog niet gestart.');if(!roster[1]?.checked)return toast('Check eerst in voor het toernooi.');const next=nodeForRick(b);if(!next)return toast('Je volgende tegenstander is nog niet bekend.');const n=next.node;if(n.matchId){ctx.openMatch(n.matchId);return;}const opp=n.players.find(id=>id!==1);if(!roster[opp]?.checked)return toast('Je tegenstander moet eerst inchecken. Gebruik eventueel Demo check-in.');const localPlayers=n.players.filter(id=>roster[id].location==='club').length;const setup=localPlayers===2?'localone':localPlayers===0?'remote':'hybrid';showModal('Jouw toernooipartij.','Controleer de opstelling voordat je naar de wedstrijdkamer gaat.',`<form data-form="comp-hall-start"><div class="dr-inline" style="margin-bottom:18px">${profile(1,true)}<span>vs</span>${profile(opp,true)}</div><input type="hidden" name="round" value="${next.round}"><input type="hidden" name="index" value="${next.index}"><input type="hidden" name="setup" value="${setup}"><p class="subtle-label">${esc(SETUPS[setup])} · ${t.score||501} · Best of ${next.round===2?7:t.bestOf||5}</p>${setup==='localone'?`<label class="field">Fysiek clubbord<select name="board"><option value="1">Bord 1</option><option value="2">Bord 2</option><option value="3">Bord 3</option><option value="4">Bord 4</option></select></label>`:`<div class="notice">${icon('wifi')}Deze partij krijgt een digitale wedstrijdkamer. Er wordt geen fysiek clubbord gereserveerd.</div>`}<div class="modal-actions">${button('Annuleren','close-modal','ghost')}<button class="btn gold">Naar de wedstrijdkamer</button></div></form>`);}
  function handleAction(action,el){if(!action.startsWith('comp-')&&!action.startsWith('hall-'))return false;init();const id=el.dataset.id;switch(action){
    case 'comp-select':if(!scopedLeagues().some(l=>l.id===C(id)))break;state().selectedLeague=C(id);state().leagueTab='standings';save();render();break;
    case 'comp-tab':state().leagueTab=el.dataset.value;save();render();break;
    case 'comp-filter':state().fixtureFilter=el.dataset.value;save();render();break;
    case 'comp-new':newLeague();break;
    case 'comp-join':{const l=scopedLeagues().find(l=>l.id===C(id));if(!l)break;if(l.clubId&&!state().clubs?.items?.find(club=>club.id===l.clubId)?.members?.some(m=>(typeof m==='number'?m:m.id)===1)){toast('Word eerst lid van deze club om aan de clubcompetitie mee te doen.');break;}if(l.players.includes(1))return true;if(l.players.length>=l.capacity){toast('Deze competitie zit vol.');break;}l.players.push(1);l.joined=true;const old=l.fixtures;l.fixtures=schedule(l.players,l.id,l.startDate).map(f=>{const existing=old.find(o=>o.players.every(p=>f.players.includes(p)));return existing?{...existing,id:f.id,round:f.round}:f;});save();render();toast('Rick is toegevoegd; het voorbeeldprogramma is bijgewerkt.');break;}
    case 'comp-plan':planFixture(id);break;
    case 'comp-accept-time':{const found=findFixture(id);if(!found||found.f.status!=='proposed')break;found.f.time=found.f.proposedTime;found.f.proposedTime=null;found.f.status='scheduled';save();render();toast('Demo: je tegenstander heeft de speeltijd geaccepteerd.');break;}
    case 'comp-start':startFixture(id);break;
    case 'comp-open-match':ctx.openMatch(C(id));break;
    case 'comp-watch':go('spectator/'+id);break;
    case 'comp-invite':copyInvite();break;
    case 'comp-lineup':lineupForm();break;
    case 'comp-simulate-fixture':{if(!adm())break;const found=findFixture(id);if(!found||found.f.status==='finished'||found.f.matchId)break;const{l,f}=found;f.score=l.legLimit?[Math.ceil(l.legLimit/2)+1,Math.floor(l.legLimit/2)-1]:[Math.ceil((l.bestOf||5)/2),1];f.status='finished';f.mockResult=true;save();render();toast('Een voorbeelduitslag is toegevoegd aan de stand.');break;}
    case 'hall-tab':if(!tournament())break;state().hallTabs??={};state().hallTabs[tournament().id]=el.dataset.value;save();render();break;
    case 'hall-community':{const t=tournament();if(!t)break;const room=communityRoomFor(t);const rid=room?.id||ctx.createCommunityRoom?.({name:`${t.name} · Spelerslounge`,type:'tournament',maxMembers:32,tournamentId:t.id,clubId:t.clubId??null,description:`De ontmoetingsplek voor deelnemers van ${t.name}. Bespreek wedstrijden en volg het toernooi samen.`});if(rid)go('community/'+rid);else toast('De toernooikamer kan momenteel niet worden geopend.');break;}
    case 'hall-checkin':{const t=tournament();if(!t)break;if(!['active','open'].includes(t.status))break;const roster=checkins(t);roster[1]??={location:'home'};roster[1].checked=true;roster[1].state='ready';save();render();toast('Je bent ingecheckt voor de toernooizaal.');break;}
    case 'hall-checkin-others':{if(!adm())break;const t=tournament();if(!t||!['active','open'].includes(t.status))break;Object.entries(checkins(t)).forEach(([id,p])=>{if(C(id)!==1){p.checked=true;p.state='ready';}});save();render();toast('Demo: de overige spelers zijn ingecheckt.');break;}
    case 'hall-start':startHall();break;
    case 'hall-simulate':{if(!adm())break;const t=tournament();if(!t||t.status!=='active')break;const b=makeBracket(t),r=b.rounds.findIndex(round=>round.some(n=>!n.winner));if(r<0)break;let count=0;b.rounds[r].forEach((n,i)=>{if(n.winner||!n.players.every(Boolean)||n.matchId)return;const win=i%2,legs=r===2?4:Math.ceil((t.bestOf||5)/2);fillWinner(b,r,i,win===0?[legs,legs-1]:[legs-1,legs]);count++;});save();render();toast(count?`${count} voorbeelduitslag${count>1?'en':''} ingevuld; winnaars gaan door.`:'Rond eerst de lopende wedstrijdkamer af.');break;}
  }return true;}
  function handleForm(form,f){const type=form.dataset.form;if(!type?.startsWith('comp-'))return false;init();const error=message=>{const el=document.getElementById('comp-form-error');if(el)el.textContent=message;};if(type==='comp-new'){if(!adm())return true;const name=f.name.trim(),division=f.division.trim(),size=C(f.size);if(!name||!division){error('Vul een competitienaam en divisie in.');return true;}const approved=participantPool();if(approved.length<size){error('Er zijn onvoldoende goedgekeurde spelers voor dit aantal.');return true;}const fixed=f.format.startsWith('fixed'),limit=C(f.format.replace(/\D/g,''));const l=seededLeague({id:Date.now(),name,division,players:approved.slice(0,size),setup:f.setup,legLimit:fixed?limit:null,bestOf:fixed?5:limit,startDate:f.date});l.fixtures.forEach(x=>{x.status='scheduled';x.score=null;delete x.mockResult;});l.cameraRequired=f.camera==='yes';l.capacity=size;l.clubId=scope();setTeamParticipants(l);state().leagues.push(l);state().selectedLeague=l.id;state().leagueTab='fixtures';save();closeModal();go('leagues');toast('Je competitie en het speelschema staan klaar.');}
    if(type==='comp-plan'){const found=findFixture(f.id);if(!found||found.f.status==='finished')return true;if(!f.time||Number.isNaN(new Date(f.time).getTime())){error('Kies een geldige datum en tijd.');return true;}found.f.proposedTime=f.time;found.f.message=f.message?.trim()||'';found.f.status='proposed';save();closeModal();render();toast('Tijdvoorstel bewaard. Simuleer het akkoord om verder te gaan.');}
    if(type==='comp-lineup'){const l=selected();if(!l)return true;const singles=l.lineup.singles.map((_,i)=>C(f['single'+i])),doubles=l.lineup.doubles.map((_,i)=>[C(f['double'+i+'0']),C(f['double'+i+'1'])]);if(new Set(singles).size!==singles.length){error('Kies voor elke single een andere speler.');return true;}if(doubles.some(pair=>pair[0]===pair[1])){error('Een dubbelkoppel bestaat uit twee verschillende spelers.');return true;}if(!f.name.trim()){error('Vul een teamnaam in.');return true;}l.teams[0].name=f.name.trim();l.lineup={singles,doubles};save();closeModal();render();toast('De teamopstelling is opgeslagen.');}
    if(type==='comp-hall-start'){const t=tournament();if(!t)return true;const b=makeBracket(t),n=b.rounds[C(f.round)]?.[C(f.index)];if(!n||n.winner||!n.players.includes(1))return true;if(n.matchId){closeModal();ctx.openMatch(n.matchId);return true;}const opponentId=n.players.find(id=>id!==1);closeModal();const mid=ctx.createGame({opponentId,startScore:t.score||501,bestOf:C(f.round)===2?7:t.bestOf||5,setup:f.setup,type:'tournament',cameraRequired:true,tournamentId:t.id,clubId:t.clubId??null,board:f.setup==='localone'?C(f.board):null});if(mid){n.matchId=mid;n.physicalBoard=f.setup==='localone'?C(f.board):null;save();}}
    return true;}
  function onFinished(match){init();const meta=state().rooms?.[match.id]||{};let updated=false;
    for(const l of state().leagues){const fixture=l.fixtures.find(f=>f.matchId===match.id||f.id===(match.fixtureId||meta.fixtureId));if(!fixture)continue;const score=fixture.players.map(id=>match.legs[match.players.indexOf(id)]);if(score.some(v=>v===undefined))continue;fixture.score=score;fixture.status='finished';fixture.mockResult=false;fixture.confirmed=true;updated=true;}
    for(const b of Object.values(state().tournamentBrackets)){b.rounds.forEach((round,ri)=>round.forEach((node,ni)=>{if(node.matchId!==match.id||node.winner)return;const score=node.players.map(id=>match.legs[match.players.indexOf(id)]);if(score.some(v=>v===undefined)||score[0]===score[1])return;fillWinner(b,ri,ni,score);updated=true;}));}
    if(updated)save();return updated;
  }
  // Selects use one delegated listener; the parent dispatches only forms/actions.
  document.addEventListener('change',e=>{if(e.target.id==='comp-hall-select'){init();state().selectedHall=C(e.target.value);save();render();}if(e.target.dataset?.hallLocation&&adm()){init();const roster=checkins(tournament());const player=roster[C(e.target.dataset.hallLocation)];if(player)player.location=e.target.value==='club'?'club':'home';save();render();}if(e.target.id==='comp-hall-location'){init();const roster=checkins(tournament());if(roster[1])roster[1].location=e.target.value==='club'?'club':'home';save();render();}});
  return {init,leagues,hall,handleAction,handleForm,onFinished,standings};
}
